'use client';

/* eslint-disable @next/next/no-img-element -- the QR is a data URL generated by our own API */
import { AnimatePresence, motion } from 'framer-motion';
import { useState } from 'react';
import { Button } from '@/components/ui/Button';
import { CodeInput } from './CodeInput';

const slide = {
  initial: { opacity: 0, x: 24 },
  animate: { opacity: 1, x: 0 },
  exit: { opacity: 0, x: -24 },
  transition: { duration: 0.25 },
};

/** Two short steps, like the User App: 1) scan the QR / copy the key, 2) enter the 6-digit code. */
export function MfaSetupStep({
  qr,
  code,
  onCode,
  error,
  busy,
  onSubmit,
}: {
  qr: { secret: string; qr: string } | null;
  code: string;
  onCode: (c: string) => void;
  error: string;
  busy: boolean;
  onSubmit: () => void;
}) {
  const [step, setStep] = useState<'scan' | 'verify'>('scan');
  const [copied, setCopied] = useState(false);
  const grouped = qr?.secret.match(/.{1,4}/g)?.join(' ') ?? '';

  async function copy() {
    try {
      await navigator.clipboard.writeText(qr?.secret ?? '');
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard unavailable: the key stays visible for manual entry */
    }
  }

  return (
    <AnimatePresence mode="wait" initial={false}>
      {step === 'scan' ? (
        <motion.div key="scan" {...slide} className="space-y-4">
          <div>
            <h2 className="text-2xl font-extrabold">Secure your account</h2>
            <p className="text-sm text-muted">Step 2 of 3 · Add Kanaku Admin to your app</p>
          </div>
          <p className="text-sm text-ink-2">
            Open Google Authenticator (or any authenticator app), tap <strong>+</strong>, and scan
            this QR code.
          </p>
          {qr ? (
            <div className="flex flex-col items-center gap-4 rounded-2xl border border-line bg-canvas p-4 sm:flex-row">
              <img
                src={qr.qr}
                alt="QR code to add Kanaku Admin to your authenticator app"
                width={160}
                height={160}
                className="shrink-0 rounded-xl bg-white p-1.5"
              />
              <div className="min-w-0 text-center sm:text-left">
                <p className="text-xs text-muted">Can&apos;t scan? Enter this key instead</p>
                <p className="mt-1 font-mono text-[13px] font-semibold tracking-wider break-all select-all">
                  {grouped}
                </p>
                <p className="mt-1 text-[11px] text-muted">
                  Account “Kanaku Admin” · type: time based
                </p>
                <button
                  type="button"
                  onClick={copy}
                  className="mt-2 text-[13px] font-semibold text-link underline"
                >
                  {copied ? 'Copied' : 'Copy key'}
                </button>
              </div>
            </div>
          ) : (
            <p className="text-sm text-muted">Loading QR code…</p>
          )}
          {error && (
            <p role="alert" className="text-sm text-bad">
              {error}
            </p>
          )}
          <Button type="button" className="w-full" disabled={!qr} onClick={() => setStep('verify')}>
            I&apos;ve added it · Continue
          </Button>
        </motion.div>
      ) : (
        <motion.form
          key="verify"
          {...slide}
          className="space-y-5"
          onSubmit={(e) => {
            e.preventDefault();
            onSubmit();
          }}
        >
          <div>
            <h2 className="text-2xl font-extrabold">Enter the code</h2>
            <p className="mt-2 text-sm text-muted">
              Step 3 of 3 · Type the 6-digit code shown for Kanaku Admin in your app.
            </p>
          </div>
          <CodeInput value={code} onChange={onCode} error={error} autoFocus />
          <Button type="submit" className="w-full" loading={busy} disabled={code.length !== 6}>
            Verify and continue
          </Button>
          <button
            type="button"
            onClick={() => setStep('scan')}
            className="w-full text-center text-[15px] font-semibold text-link underline"
          >
            ← Back to QR code
          </button>
        </motion.form>
      )}
    </AnimatePresence>
  );
}
